## Code Example

```javascript
function solve() {
  for (let A = 0; A <= 1; A++) {
    for (let B = 0; B <= 1; B++) {
      for (let C = 0; C <= 1; C++) {
        const ok1 = (!A) || B;     // A -> B
        const ok2 = (!B) || (!C);  // B -> ¬C
        const ok3 = (A || B || C); // at least one true
